      "ja": "廃ガスを除去するためのもの，例．ガスの煙道（独立して立っている煙突Ｅ０４Ｈ１２／２８；暖炉と煙突とを連結するもの，煙突の付属具，煙突の清掃穴のおおいＦ２３Ｊ；煙突の先端Ｆ２３Ｌ）；そのために特に設計された建築物の要素，例．そのために形造られた煉瓦または組み物",
      "en": "for carrying away waste gases, e.g. flue gases (free-standing chimneys E04H 12/28; connections between fireplace and chimney, chimney fittings, covers for cleaning holes of chimneys F23J; chimney tops F23L); Building elements specially designed therefor, e.g. shaped bricks or sets thereof",
